const KEY='loose-ends-v1';
const initial=()=>({stage:0,coverage:false,approved:false,arrival:false,closed:false,waiting:false,events:[],messages:[{role:'bot',text:'What’s going on at home?\n\nTry the washer example below. We’ll keep the details here for whoever takes over.'}]});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||initial();if(!Array.isArray(state.messages)||!Array.isArray(state.events))state=initial()}catch{state=initial()}
if(state.messages.length===1 && state.stage===0)state.messages=initial().messages;
const $=id=>document.getElementById(id);const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function add(text){state.messages.push({role:'bot',text})}function event(text){state.events.push({text,time:new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})})}
function suggestions(){if(!state.stage)return ['The washer leaked. Water is off. The technician is coming 2–4, but I leave at 1.'];if(state.closed)return ['What do I need to know?'];if(state.arrival)return ['It’s working again.','We’re waiting for a replacement part.'];if(!state.coverage)return ['Alex can cover, but only after 3.','What do I need to know?'];if(!state.approved)return ['Draft a message to the technician.','What do I need to know?'];return ['What do I need to know?','The technician came.']}
function render(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}$('count').textContent=state.stage&&!state.closed?'1':'0';$('board').innerHTML=!state.stage?'<div class="empty"><span>⌁</span><b style="color:var(--ink)">Nothing on the list yet.</b><br>Try the washer example in the conversation.<br>The repair and its next steps will show up here.</div>':`<article class="card"><div class="card-body"><div class="card-head"><span class="icon">▤</span><div><h3>The washer repair</h3><span class="meta">Household repair · ${state.closed?'Resolved':'Open situation'}</span></div></div><span class="badge" style="${state.closed?'background:#e7efdf;color:#46613c':''}">${state.closed?'Done ✓':state.waiting?'Waiting on a part':state.arrival?'Outcome needed':state.approved?'Handoff ready':'Needs attention'}</span><div class="facts">${state.closed?'The washer is working again. No next action needed.':`Washer leaked. Water supply is off.<br>Technician window: <b>2–4 p.m.</b><br>You leave at <b>1 p.m.</b>${state.coverage?'<br>Alex can meet them <b>after 3 p.m.</b>':''}`}</div>${!state.closed?`<div class="alert"><b>${state.waiting?'Keep this open':state.arrival?'Did the repair work?':state.approved?'Awaiting a reply':state.coverage?'There’s still a gap':'Who can be there?'}</b>${state.waiting?'Replacement part is pending. Ask for a delivery estimate and a return visit.':state.arrival?'Confirm whether the washer works or there’s another step.':state.approved?'The demo message is approved. A later arrival is requested, not confirmed.':state.coverage?'The technician could arrive between 2 and 3, before Alex is available.':'Someone needs to meet the technician between 2 and 4.'}</div>`:''}</div><div class="card-foot"><span>${state.coverage?'◉ Alex · available after 3':'◌ Coverage unassigned'}</span><span>${state.closed?'Completed':'Shared with household'}</span></div></article>`;
$('timeline').innerHTML=state.events.length?state.events.slice().reverse().map(e=>`<div class="event"><b>${escape(e.text)}</b><br>${escape(e.time)} · Demo household</div>`).join(''):'<div class="event">No updates yet.</div>';
$('messages').innerHTML=state.messages.map(m=>`<div class="message ${m.role==='bot'?'bot':'user'}"><div class="speaker">${m.role==='bot'?'Loose Ends':'You'}</div>${escape(m.text)}</div>`).join('');$('suggestions').innerHTML='';for(const s of suggestions()){const b=document.createElement('button');b.textContent=s;b.onclick=()=>send(s);$('suggestions').append(b)}$('messages').scrollTop=$('messages').scrollHeight;
}
function send(text){text=text.trim();if(!text)return;state.messages.push({role:'user',text});$('input').value='';const t=text.toLowerCase();
if(/what.*(know|status)|handoff|catch me up|where.*stand/.test(t)){add(!state.stage?'There’s nothing recorded yet. Tell me about the washer repair to start the shared handoff.':state.closed?'The washer repair is resolved: you confirmed it’s working again. There are no remaining actions.':`Here’s the handoff:\n• The washer leaked and its water is off.\n• The technician’s original window is 2–4 p.m.\n• ${state.coverage?'Alex can cover after 3.':'Nobody is assigned to meet them yet.'}\n• ${state.waiting?'A replacement part is pending. Get an ETA and arrange the return visit.':state.arrival?'The technician visited. We still need to confirm the result.':state.approved?'A request for an arrival after 3 was approved in this demo. The technician has not confirmed it.':state.coverage?'The 2–3 p.m. gap still needs resolving.':'You leave at 1, so we need coverage.'}`)}
else if(!state.stage){if(/washer|washing|leak/.test(t)){state.stage=1;event('Washer repair opened · coverage needed');add('Got it. Water’s off, the technician is due 2–4, and you’re leaving at 1.\n\nWho can be home to let them in?')}else add('This prototype follows the washer repair story. Try the suggested first update to see how a household handoff works.')}
else if(/working again|fixed|resolved/.test(t)){state.closed=true;state.waiting=false;event('Washer confirmed working · loose end closed');add('Great, I’ve marked it done. The repair history is still here if anyone needs it.')}
else if(/replacement|waiting.*part/.test(t)){state.arrival=true;state.waiting=true;event('Repair remains open · replacement part pending');add('Okay, it stays open. We still need a delivery estimate for the part and a date for the return visit.\n\nI’ve added that to the handoff.')}
else if(/technician (came|arrived|visited)|visit.*done/.test(t)){state.arrival=true;event('Technician visited · outcome not yet confirmed');add('Did they get the washer working, or are we waiting on something?')}
else if(/alex|cover.*after|after.*3/.test(t)){state.coverage=true;event('Alex available after 3 · timing conflict detected');add('That leaves 2–3 uncovered. Should we ask the technician to come after 3?\n\nUntil they confirm, the window is still 2–4.')}
else if(/draft|message|request/.test(t)&&!/approve/.test(t)){if(!state.coverage)add('First, tell me who can meet the technician and when. Then I can draft a useful request.');else{add('Draft to the technician:\n“Hi! For today’s washer visit, could you arrive between 3 and 4 p.m.? Alex will be home after 3. Please confirm whether that works. Thank you.”\n\nApprove this demo message? Nothing will be sent externally.');render();const b=document.createElement('button');b.textContent='Approve demo message';b.onclick=()=>send('Approve demo message');$('suggestions').prepend(b);return}}
else if(/approve|send it|yes/.test(t)&&state.coverage){state.approved=true;event('Message approved in demo · awaiting technician confirmation');add('Approved for the demo; nothing was sent.\n\nWe’re still waiting for the technician to agree to after 3. I’ve left that in Alex’s handoff.')}
else add('I can track the washer repair in this demo. Tell me Alex’s availability, ask for a handoff, draft a technician message, or report whether the repair is finished.');render()}
$('form').onsubmit=e=>{e.preventDefault();send($('input').value)};$('input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send($('input').value)}};$('handoff').onclick=()=>send('What do I need to know?');$('home').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('about').onclick=()=>$('modal').classList.remove('hidden');$('close').onclick=()=>$('modal').classList.add('hidden');$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').classList.add('hidden')};document.onkeydown=e=>{if(e.key==='Escape')$('modal').classList.add('hidden')};$('reset').onclick=()=>{if(confirm('Clear this browser’s demo history and start again?')){state=initial();render()}};render();
